// What the chat page sent: { sessionId, message, files: [{ file_id, name, kind }] }
const b = $input.first().json.body || {};
const files = Array.isArray(b.files) ? b.files : [];
const message = String(b.message || '').trim();
const words = (s) => s.split(/\s+/).filter(Boolean).length;
const lines = message.split('\n').filter((l) => l.trim()).length;
return [{ json: {
  sessionId: String(b.sessionId || ''),
  // agent memory key: changes when the chat is cleared, so the agent forgets the old chat
  memoryKey: String(b.memoryKey || b.sessionId || ''),
  message,
  fileIds: files.map((f) => f.file_id),
  fileNames: files.map((f) => `${f.name} (${f.kind})`),
  hasFiles: files.length > 0,
  // pasted meeting notes, not a question: more than ~150 words,
  // or a short list of typed notes (4+ lines and 30+ words)
  isLongPaste: words(message) > 150 || (lines >= 4 && words(message) >= 30),
} }];

// Give the agent a short message + what the session already contains.
// The full notes never go to the agent: the make_minutes tool reads them itself.
const p = $('Prepare input').first().json;
const s = $input.first().json;
const notes = s.notes.length ? s.notes.map((n) => `${n.source} (${n.words} words)`).join('; ') : 'none';
const draft = s.draft
  ? `a draft "${s.draft.title}" exists, status: ${s.draft.status}, ${s.draft.actions} actions`
  : 'no draft yet';
let msg = p.message;
if (p.isLongPaste) {
  const words = msg.split(/\s+/);
  msg = `[I pasted meeting notes (${words.length} words), saved in the session notes. Start: "${words.slice(0, 40).join(' ')} …"]`;
}
if (!msg && p.hasFiles) msg = '[I sent files only. Their text is saved in the session notes.]';
const chatInput = `${msg}\n\n(System info, not written by the user: meeting notes in this session: ${notes}. Minutes: ${draft}.)`;
// A clear approval of a draft skips the AI: sending email must not depend on the model
// choosing the right tool (a 7B model sometimes answers "sent!" without calling it).
const approveWords = /^(approve|approved|ok,? send( it)?|send( it)?|yes,? send( it)?|valider|je valide|valid[eé]|approuv[eé]r?)[\s.!]*$/i;
const isApproval = !!s.draft && approveWords.test(p.message);
// New meeting material (files or pasted notes) + a request for minutes (or no text at all)
// also skips the AI choice: the model sometimes answered "no notes yet" right after a photo.
const asksMinutes = /minutes|compte[- ]rendu|proc[eè]s[- ]verbal|\bpv\b|r[eé]sum|summar/i;
const isMinutesRequest = !isApproval && (p.hasFiles || p.isLongPaste) && (!p.message || asksMinutes.test(p.message));
// 0 = approve directly, 1 = make the minutes directly, 2 = let the AI agent decide
const route = isApproval ? 0 : (isMinutesRequest ? 1 : 2);
return [{ json: { sessionId: p.sessionId, chatInput, isApproval, route } }];

// Answer for the chat page + the list of tools the agent used (shown under the answer).
const out = $input.first().json;
const steps = (out.intermediateSteps || []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  result: String(typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation)).slice(0, 600),
}));
// A small model can answer as if a failed tool had worked, or claim an action without any tool:
// say so under the answer.
const failed = steps.filter((s) => /"error"|^Error|error:/i.test(s.result));
let reply = out.output || '';
if (failed.length) reply += `\n\nWarning: ${failed.map((s) => s.tool).join(', ')} failed, so this answer may be wrong. See the step details.`;
const claimsAction = /\b(updated|changed|corrected|fixed|sent|emailed|created|added|saved)\b|(modifi|corrig|envoy|cré|ajout|enregistr)(é|e)/i;
if (!steps.length && claimsAction.test(reply)) reply += '\n\n(Note: no tool ran in this turn, so nothing was changed, sent or saved just now.)';
return [{ json: { reply, steps } }];

const err = $input.first().json.error;
const text = typeof err === 'string' ? err : (err?.message || JSON.stringify($input.first().json).slice(0, 300));
return [{ json: { reply: `Sorry, the AI step failed: ${text}. Is Ollama running with the model downloaded?`, steps: [], error: text } }];

// Same shape as the agent's answer, so the page shows the tool that ran.
const sessionId = $('Build agent input').first().json.sessionId;
const result = String($input.first().json.result || 'Approved.');
const reply = result.replace(/\s*Tell the user in short\.?\s*$/, '');
return [{ json: { reply, steps: [{ tool: 'approve_minutes', input: { sessionId }, result: result.slice(0, 600) }] } }];

const err = $input.first().json.error;
const text = (typeof err === 'string' ? err : (err?.message || JSON.stringify($input.first().json).slice(0, 300)))
  .replace(/\s*\[line \d+\]/, '');
const hint = /access token|oauth|credential/i.test(text)
  ? ' Google is not connected yet: in n8n open Credentials and click "Sign in with Google" on the Gmail, Tasks, Calendar and Sheets credentials.'
  : '';
const retry = /already approved/i.test(text) ? ''
  : ' What was already done is saved: after fixing the problem, approve again and nothing is sent twice.';
return [{ json: { reply: `Approval stopped: ${text}.${retry}${hint}`, steps: [], error: text } }];

// Same shape as the agent's answer, so the page shows the tool that ran.
const sessionId = $('Build agent input').first().json.sessionId;
const result = String($input.first().json.result || '');
const reply = result
  .replace(/^Draft saved and already shown to the user in the chat:\s*/, 'The minutes draft is ready: ')
  .replace(/\s*Tell the user\.?/, '')
  .replace(/\s*Ask the user to approve it.*$/, ' Check it, then click **Approve and send**, or tell me what to change.');
return [{ json: { reply, steps: [{ tool: 'make_minutes', input: { sessionId }, result: result.slice(0, 600) }] } }];

const err = $input.first().json.error;
const text = (typeof err === 'string' ? err : (err?.message || JSON.stringify($input.first().json).slice(0, 300)))
  .replace(/\s*\[line \d+\]/, '');
return [{ json: { reply: `Could not write the minutes: ${text}. Is Ollama running with the model downloaded?`, steps: [], error: text } }];

// Ollama structured output: `format` = JSON schema, the model must fill exactly these fields.
const input = $('Tool call').first().json;
const notes = $('Get meeting notes').first().json;
const draft = $input.first().json;
const hasDraft = Boolean(draft && draft.markdown);
const today = $now.toFormat('yyyy-MM-dd (cccc)');

if (input.changes && !hasDraft) throw new Error('There is no draft to change yet. Make the minutes first.');
if (!input.changes && !notes.text) throw new Error('No meeting notes in this session yet. Ask the user to send a recording, photos or notes.');

const SCHEMA = {
  type: 'object',
  properties: {
    title: { type: 'string' },
    date: { type: 'string' },
    attendees: { type: 'array', items: { type: 'string' } },
    summary: { type: 'string' },
    decisions: { type: 'array', items: { type: 'string' } },
    actions: { type: 'array', items: { type: 'object', properties: {
      what: { type: 'string' }, owner: { type: 'string' }, due_date: { type: 'string' } },
      required: ['what', 'owner', 'due_date'] } },
    postponed: { type: 'array', items: { type: 'string' } },
    next_meeting: { type: 'object', properties: { date: { type: 'string' }, time: { type: 'string' } },
      required: ['date', 'time'] },
  },
  required: ['title', 'date', 'attendees', 'summary', 'decisions', 'actions', 'postponed', 'next_meeting'],
};

// Language of the notes, guessed from common short words. Told to the model explicitly:
// with only a rule like "same language as the notes" it translated a German photo into French.
const sourceText = input.changes ? JSON.stringify(draft) : notes.text;
const tokens = String(sourceText).toLowerCase().match(/[a-zäöüßàâçéèêëîïôûù]+/g) || [];
const STOP = {
  English: ['the', 'and', 'to', 'of', 'is', 'we', 'will', 'for', 'with', 'by', 'next', 'meeting'],
  French: ['le', 'la', 'les', 'et', 'des', 'du', 'pour', 'avec', 'est', 'une', 'réunion', 'prochaine'],
  German: ['der', 'die', 'das', 'und', 'ist', 'mit', 'für', 'bis', 'wer', 'was', 'nicht', 'aufstellen'],
};
const score = Object.fromEntries(Object.entries(STOP).map(([l, w]) => [l, tokens.filter((t) => w.includes(t)).length]));
// accents are a strong hint on boards with only headings and names
score.French += tokens.filter((t) => /[éèêàçùûôîë]/.test(t)).length;
score.German += tokens.filter((t) => /[äöüß]/.test(t)).length;
const best = Object.keys(score).sort((a, b) => score[b] - score[a])[0];
const language = score[best] > 0 ? best : '';
const fromPhoto = /### photo text/.test(String(notes.text || ''));

const system = [
  'You are a meeting secretary. You write clear, short meeting minutes from raw notes,',
  'audio transcripts and text read from whiteboard photos.',
  'Rules:',
  '- Use only facts from the notes. Never invent names, numbers, dates or decisions.',
  language ? `- The notes are in ${language}. Write every text field in ${language}. Never translate.`
    : '- Write every text field in the same language as the notes. Never translate.',
  '- attendees: only people the notes say were present (for example after "Present:", "Présents :", "Anwesend:"),',
  '  or people who speak in a transcript. If the notes do not say who was there, return an empty list.',
  '- summary: 3 to 6 sentences.',
  '- decisions: what the group agreed, one short sentence each. A task with an owner is an action, not a decision.',
  '- actions: only tasks someone must do after the meeting. A topic or heading is not an action,',
  '  and an agenda point ("tool training", "get to know each other") is not an action.',
  '  what = starts with a verb. owner = the person or team written next to that task in the notes, else "unassigned".',
  '  A topic, heading or department name of the agenda is never an owner.',
  `  due_date = YYYY-MM-DD if a deadline was said (today is ${today}; turn "next Friday" into a date), else "".`,
  '- postponed: topics discussed but not finished, or moved to a later meeting.',
  '- Put each item in one list only: never repeat an action as a postponed topic.',
  '- Whiteboard photos often show only topic headings: then describe them in the summary and leave actions empty.',
  '- next_meeting: date YYYY-MM-DD and time HH:MM if decided, else empty strings.',
  `- date: the meeting date YYYY-MM-DD; if unknown use ${today.slice(0, 10)}.`,
  '- Transcripts contain recognition mistakes and tags like {vocalsound} or {disfmarker}: ignore them.',
  ...(fromPhoto ? [
    '- Part of the notes was read from a photo of a board or notebook. A photo does not show who was in the room:',
    '  leave attendees empty unless the board itself lists the people present. Names next to tasks are owners.',
  ] : []),
].join('\n');

let user;
if (input.changes) {
  const { title, date, attendees, summary, decisions, actions, postponed, next_meeting } = draft;
  user = `Current minutes (JSON):\n${JSON.stringify({ title, date, attendees, summary, decisions, actions, postponed, next_meeting })}\n\n`
    + `Apply this change and return the full updated minutes: ${input.changes}`;
} else {
  user = `Meeting title: ${input.title || '(find it in the notes)'}\n`
    + `Meeting date: ${input.date || '(find it in the notes)'}\n`
    + `Attendees: ${input.attendees || '(find them in the notes)'}\n\nMeeting notes:\n${notes.text}`;
}

return [{ json: {
  body: {
    model: $env.MINUTEPILOT_TEXT_MODEL,
    stream: false,
    format: SCHEMA,
    options: { temperature: 0.2, num_ctx: Number($env.MINUTEPILOT_NUM_CTX) || 8192 },
    messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  },
  notesInfo: (input.changes ? 'changing the current draft'
    : `${notes.words} words of notes` + (notes.truncated ? ` — too long, using only the first ${notes.used_words}` : ''))
    + ` · language: ${language || 'not sure'}`,
} }];

// Parse the model's JSON, clean it, and render the Markdown the chat page and the email show.
const input = $('Tool call').first().json;
const old = $('Get current draft').first().json;
let m;
try { m = JSON.parse($input.first().json.message.content); }
catch (e) { throw new Error('The AI did not return valid JSON. Try again.'); }

const list = (a) => (Array.isArray(a) ? a : []).map((x) => String(x).trim()).filter(Boolean);
const isDate = (d) => /^\d{4}-\d{2}-\d{2}$/.test(String(d || ''));
const draft = {
  title: String(m.title || input.title || 'Meeting').trim(),
  date: isDate(m.date) ? m.date : (isDate(input.date) ? input.date : $now.toFormat('yyyy-MM-dd')),
  attendees: list(m.attendees),
  summary: String(m.summary || '').trim(),
  decisions: list(m.decisions),
  actions: (Array.isArray(m.actions) ? m.actions : []).filter((a) => a && a.what).map((a) => ({
    what: String(a.what).trim(),
    owner: String(a.owner || 'unassigned').trim() || 'unassigned',
    due_date: isDate(a.due_date) ? a.due_date : '',
  })),
  postponed: list(m.postponed),
  next_meeting: { date: isDate(m.next_meeting?.date) ? m.next_meeting.date : '', time: String(m.next_meeting?.time || '') },
};
// A name must appear in what the user gave us (notes, the change asked, the previous draft):
// the model sometimes invents attendees ("Alice, Bob…") for a photo. Unknown names are removed.
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const source = norm([$('Get meeting notes').first().json.text, input.changes, input.attendees,
  input.changes ? JSON.stringify({ a: old.attendees, o: (old.actions || []).map((a) => a.owner) }) : ''].join('\n'));
const known = (name) => norm(name).split(/[^a-z0-9]+/).some((t) => t.length >= 3 && source.includes(t));
const removed = [];
draft.attendees = draft.attendees.filter((n) => known(n) || !removed.push(n));
for (const a of draft.actions) {
  if (a.owner !== 'unassigned' && !known(a.owner)) { removed.push(a.owner); a.owner = 'unassigned'; }
}
draft.removed_names = [...new Set(removed)];

// The model often repeats each task ("Paul will send the design…") or postponed topic as a decision.
// Drop such a decision: it names the task's owner and has most of the task's words, or it is a postponed topic.
const stems = (s) => norm(s).split(/[^a-z0-9]+/).filter((t) => t.length >= 4).map((t) => t.slice(0, 5));
const covers = (text, item) => {
  const want = stems(item); const have = new Set(stems(text));
  return want.length > 0 && want.filter((x) => have.has(x)).length / want.length >= 0.6;
};
draft.decisions = draft.decisions.filter((d) =>
  !draft.actions.some((a) => a.owner !== 'unassigned' && norm(d).includes(norm(a.owner)) && covers(d, a.what))
  && !draft.postponed.some((p) => covers(d, p)));

const slug = draft.title.toLowerCase().normalize('NFD').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 30);
draft.meeting_id = (input.changes && old.meeting_id) ? old.meeting_id : `${draft.date}-${slug}-${$now.toFormat('HHmmss')}`;

const md = [`# ${draft.title}`, '', `**Date:** ${draft.date}`,
  `**Attendees:** ${draft.attendees.join(', ') || '(not given)'}`, '', '## Summary', draft.summary || '(none)', '',
  '## Decisions', ...(draft.decisions.length ? draft.decisions.map((d) => `- ${d}`) : ['- (none)']), '',
  '## Actions', ...(draft.actions.length
    ? draft.actions.map((a, i) => `${i + 1}. ${a.what} — **${a.owner}**${a.due_date ? ` — due ${a.due_date}` : ''}`)
    : ['- (none)']), '',
  '## Postponed topics', ...(draft.postponed.length ? draft.postponed.map((p) => `- ${p}`) : ['- (none)']), '',
  '## Next meeting', draft.next_meeting.date ? `${draft.next_meeting.date} ${draft.next_meeting.time}`.trim() : '(not decided)'];
draft.markdown = md.join('\n');
return [{ json: draft }];

const d = $input.first().json;
const count = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;
const removed = (d.removed_names || []).length
  ? ` Names not found in the notes were removed: ${d.removed_names.join(', ')}. Tell the user.` : '';
return [{ json: { result: `Draft saved and already shown to the user in the chat: "${d.title}" (${d.date}), `
  + `${count(d.decisions.length, 'decision')}, ${count(d.actions.length, 'action')}, `
  + `${count(d.postponed.length, 'postponed topic')}.${removed} `
  + 'Ask the user to approve it or to say what to change. Do not repeat the draft.' } }];

// ---- shared helpers (same copy in each Code node that needs them) ----
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
function mdToHtml(md) {
  const out = []; let list = null;
  const close = () => { if (list) { out.push(`</${list}>`); list = null; } };
  const inline = (s) => esc(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
  for (const line of String(md).split('\n')) {
    let m;
    if ((m = line.match(/^(#{1,3})\s+(.*)/))) { close(); const n = m[1].length; out.push(`<h${n}>${inline(m[2])}</h${n}>`); }
    else if ((m = line.match(/^\s*[-*]\s+(.*)/))) { if (list !== 'ul') { close(); list = 'ul'; out.push('<ul>'); } out.push(`<li>${inline(m[1])}</li>`); }
    else if ((m = line.match(/^\s*\d+[.)]\s+(.*)/))) { if (list !== 'ol') { close(); list = 'ol'; out.push('<ol>'); } out.push(`<li>${inline(m[1])}</li>`); }
    else if (!line.trim()) close();
    else { close(); out.push(`<p>${inline(line)}</p>`); }
  }
  close();
  return `<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.5">${out.join('\n')}</div>`;
}

const draft = $input.first().json;
if (draft.status === 'approved') throw new Error('These minutes were already approved and sent.');

// SAFETY: test mode. Every attendee gets an alias of the owner's own Gmail (owner+name@gmail.com).
const owner = String($env.MINUTEPILOT_OWNER_EMAIL || '').trim().toLowerCase();
const [local, domain] = owner.split('@');
if (!local || !domain) throw new Error('MINUTEPILOT_OWNER_EMAIL is not set in docker/.env');
const slug = (name) => name.toLowerCase().normalize('NFD').replace(/[^a-z0-9]/g, '').slice(0, 20);
const emails = [owner, ...draft.attendees.map(slug).filter(Boolean).map((s) => `${local}+${s}@${domain}`)];
const allowed = new RegExp(`^${local.replace(/[.]/g, '\\.')}(\\+[a-z0-9]+)?@${domain.replace(/[.]/g, '\\.')}$`);
for (const e of emails) if (!allowed.test(e)) throw new Error(`Blocked email address: ${e}`);

const to = [...new Set(emails)];
const ownerEmail = (name) => (slug(name) && slug(name) !== 'unassigned' ? `${local}+${slug(name)}@${domain}` : owner);
// Steps an earlier approval already did before it failed: skipped, so a retry sends nothing twice.
return [{ json: {
  draft,
  done: draft.done || {},
  to: to.join(', '),
  toCount: to.length,
  subject: `Minutes: ${draft.title} (${draft.date})`,
  html: mdToHtml(draft.markdown) + '<p style="color:#888;font-size:12px">Sent by MinutePilot after approval.</p>',
  ownerEmails: Object.fromEntries(draft.actions.map((a) => [a.owner, ownerEmail(a.owner)])),
} }];

const { draft, done } = $('Check draft and recipients').first().json;
const made = done.tasks || {};
return draft.actions.map((a, index) => ({ a, index })).filter(({ index }) => !made[index]).map(({ a, index }) => ({ json: {
  title: a.what,
  notes: `Owner: ${a.owner}
From meeting: ${draft.title} (${draft.date})`,
  // Google Tasks wants RFC 3339 with a time zone and keeps only the date part
  due: a.due_date ? `${a.due_date}T00:00:00.000Z` : '',
  index,
} }));

// Own branch, after the tasks branch: one row per action with the task id from this try
// or from an earlier one that failed later on.
const { draft, done, ownerEmails } = $('Check draft and recipients').first().json;
if (done.action_rows) return [];
const ids = { ...(done.tasks || {}) };
try {
  const asked = $('One item per action').all();
  $('Create task').all().forEach((t, i) => { if (t.json.id) ids[asked[i].json.index] = t.json.id; });
} catch (e) { /* no task created in this try */ }
return draft.actions.map((a, i) => ({ json: {
  meeting_id: draft.meeting_id, meeting_date: draft.date, action: a.what, owner: a.owner,
  owner_email: ownerEmails[a.owner] || '', due_date: a.due_date, task_id: ids[i] || '',
  created_at: $now.toISO(),
} }));

// Deadlines (09:00-09:30 on the due date) + the next meeting if one was decided.
const { draft, done } = $('Check draft and recipients').first().json;
const items = draft.actions.filter((a) => a.due_date).map((a) => ({
  summary: `Deadline: ${a.what} (${a.owner})`,
  start: `${a.due_date}T09:00:00`, end: `${a.due_date}T09:30:00`,
  description: `From meeting: ${draft.title} (${draft.date})`,
}));
const nm = draft.next_meeting || {};
if (nm.date) {
  const time = /^\d{2}:\d{2}$/.test(nm.time) ? nm.time : '10:00';
  const [h, m] = time.split(':').map(Number);
  const end = `${String(h + 1).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
  items.push({ summary: `Next meeting: ${draft.title}`, start: `${nm.date}T${time}:00`, end: `${nm.date}T${end}:00`,
    description: `Postponed topics:\n${draft.postponed.map((p) => '- ' + p).join('\n') || '(none)'}` });
}
// skip events an earlier try already created
const made = done.calendar || {};
return items.map((json, index) => ({ json: { ...json, index } })).filter((i) => !made[i.json.index]);

const { draft, done } = $('Check draft and recipients').first().json;
if (done.postponed) return [];
return draft.postponed.map((topic) => ({ json: {
  meeting_id: draft.meeting_id, meeting_date: draft.date, topic, status: 'open' } }));

const { draft, done } = $('Check draft and recipients').first().json;
if (done.register) return [];
return [{ json: {
  meeting_id: draft.meeting_id, date: draft.date, title: draft.title, attendees: draft.attendees.join(', '),
  summary: draft.summary, decisions: draft.decisions.join(' | '), postponed: draft.postponed.join(' | '),
  next_meeting: `${draft.next_meeting.date} ${draft.next_meeting.time}`.trim(), approved_at: $now.toISO(),
} }];

const count = (name) => { try { return $(name).all().length; } catch (e) { return 0; } };
const c = $('Check draft and recipients').first().json;
const before = Object.keys(c.done);
return [{ json: { result: (c.done.email ? 'The email had already been sent by the earlier try. '
  : `Done. Minutes emailed to ${c.toCount} address(es) (${c.to}). `)
  + `${count('Create task')} Google Tasks and ${count('Create calendar event')} calendar events created. `
  + 'The meeting is saved in the register (Google Sheets). '
  + (before.length ? `Skipped because already done before: ${before.join(', ')}. ` : '')
  + 'Tell the user in short.' } }];

// Skip the email if an earlier try already sent it
const c = $input.first().json;
return c.done.email ? [] : [$input.first()];

// After recording what worked: stop here if one item failed, so the minutes stay unapproved
const failed = $('Create task').all().filter((i) => i.json.error);
if (failed.length) throw new Error(`Create task: ${failed.length} failed: ${JSON.stringify(failed[0].json.error).slice(0, 200)}`);
return $input.all();

// After recording what worked: stop here if one item failed, so the minutes stay unapproved
const failed = $('Create calendar event').all().filter((i) => i.json.error);
if (failed.length) throw new Error(`Create calendar event: ${failed.length} failed: ${JSON.stringify(failed[0].json.error).slice(0, 200)}`);
return $input.all();

// email mode: only a meeting that starts in exactly 2 days. chat mode: the next event, if any.
const s = $('Settings').first().json;
const events = $input.all().map((i) => i.json).filter((e) => e.id && !String(e.summary || '').startsWith('Deadline:'));
const startOf = (e) => e.start?.dateTime || e.start?.date || '';
let meeting = events[0] || null;
if (s.mode === 'email') {
  // object form: in Code nodes plus(2, 'days') would add 2 milliseconds
const target = $now.plus({ days: 2 }).toFormat('yyyy-MM-dd');
  meeting = events.find((e) => startOf(e).slice(0, 10) === target) || null;
  if (!meeting) return []; // nothing to prepare today
}
return [{ json: { meeting: meeting ? { title: meeting.summary || 'Meeting', start: startOf(meeting) } : null } }];

const { meeting } = $('Pick meeting').first().json;
const tasks = $('Open tasks (agenda)').all().map((i) => i.json).filter((t) => t.title);
const topics = $input.all().map((i) => i.json).filter((r) => r.topic && r.status !== 'closed');
const lines = [
  `Next meeting: ${meeting ? `${meeting.title} on ${meeting.start}` : 'date not set'}`,
  '', 'Postponed topics from earlier meetings:', ...(topics.length ? topics.map((t) => `- ${t.topic} (from ${t.meeting_date})`) : ['- none']),
  '', 'Open tasks:', ...(tasks.length ? tasks.map((t) => `- ${t.title}${t.due ? ` (due ${String(t.due).slice(0, 10)})` : ''}`) : ['- none']),
];
const system = 'You prepare the agenda (ordre du jour) of a meeting. Use only the information given. '
  + 'Write Markdown: a title line "# Agenda: <meeting>", then a numbered list: 1. Approval of the last minutes, '
  + 'then one item per postponed topic, then "Follow-up of open actions" with the tasks as sub-bullets, then "Any other business". '
  + 'Write in French if the topics are in French, else English. No extra comments.';
return [{ json: {
  body: { model: $env.MINUTEPILOT_TEXT_MODEL, stream: false, options: { temperature: 0.2, num_ctx: 4096 },
    messages: [{ role: 'system', content: system }, { role: 'user', content: lines.join('\n') }] },
  meetingTitle: meeting ? meeting.title : 'next meeting', counts: `${topics.length} postponed topics, ${tasks.length} open tasks`,
} }];

// ---- shared helpers (same copy in each Code node that needs them) ----
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
function mdToHtml(md) {
  const out = []; let list = null;
  const close = () => { if (list) { out.push(`</${list}>`); list = null; } };
  const inline = (s) => esc(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
  for (const line of String(md).split('\n')) {
    let m;
    if ((m = line.match(/^(#{1,3})\s+(.*)/))) { close(); const n = m[1].length; out.push(`<h${n}>${inline(m[2])}</h${n}>`); }
    else if ((m = line.match(/^\s*[-*]\s+(.*)/))) { if (list !== 'ul') { close(); list = 'ul'; out.push('<ul>'); } out.push(`<li>${inline(m[1])}</li>`); }
    else if ((m = line.match(/^\s*\d+[.)]\s+(.*)/))) { if (list !== 'ol') { close(); list = 'ol'; out.push('<ol>'); } out.push(`<li>${inline(m[1])}</li>`); }
    else if (!line.trim()) close();
    else { close(); out.push(`<p>${inline(line)}</p>`); }
  }
  close();
  return `<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.5">${out.join('\n')}</div>`;
}

const p = $('Build agenda prompt').first().json;
const agenda = String($input.first().json.message?.content || '').trim();
return [{ json: { agenda, html: mdToHtml(agenda), subject: `Draft agenda: ${p.meetingTitle}`, counts: p.counts,
  mode: $('Settings').first().json.mode } }];

