const today = $now.toFormat('yyyy-MM-dd');
const due = $input.all().map((i) => i.json).filter((t) => t.title && t.due && String(t.due).slice(0, 10) <= today);
if (!due.length) return []; // nothing to remind: no email
const lines = due.map((t) => {
  const d = String(t.due).slice(0, 10);
  return `- ${d < today ? '**LATE** ' : ''}${t.title} — due ${d}${t.notes ? ` (${t.notes.split('\n')[0]})` : ''}`;
});
const md = [`# Tasks to check today (${today})`, '', ...lines].join('\n');
return [{ json: { subject: `MinutePilot: ${due.length} task(s) late or due today`, html: mdToHtml(md) } }];

const tasks = $input.all().map((i) => i.json).filter((t) => t.title);
const text = tasks.length
  ? tasks.map((t) => `- ${t.title}${t.due ? ` (due ${String(t.due).slice(0, 10)})` : ''}${t.notes ? ` — ${t.notes.split('\n')[0]}` : ''}`).join('\n')
  : 'No open tasks.';
return [{ json: { result: `Open tasks (${tasks.length}):\n${text}` } }];

const ev = $input.all().map((i) => i.json).filter((e) => e.id);
const text = ev.length
  ? ev.map((e) => `- ${(e.start?.dateTime || e.start?.date || '').replace('T', ' ').slice(0, 16)}: ${e.summary || '(no title)'}`).join('\n')
  : 'Nothing in the calendar for the next 60 days.';
return [{ json: { result: `Upcoming events:\n${text}` } }];

// Simple keyword search: score = how many query words appear in the meeting row.
const q = String($('Tool call').first().json.query || '').toLowerCase();
const words = q.split(/[^\p{L}\p{N}]+/u).filter((w) => w.length > 2);
const rows = $input.all().map((i) => i.json).filter((r) => r.meeting_id);
const scored = rows.map((r) => {
  const text = `${r.title} ${r.summary} ${r.decisions} ${r.postponed}`.toLowerCase();
  return { r, score: words.length ? words.filter((w) => text.includes(w)).length : 1 };
}).filter((x) => x.score > 0).sort((a, b) => b.score - a.score || String(b.r.date).localeCompare(String(a.r.date))).slice(0, 3);
const text = scored.length
  ? scored.map(({ r }) => `- ${r.date} · ${r.title}\n  Decisions: ${r.decisions || '(none)'}\n  Postponed: ${r.postponed || '(none)'}`).join('\n')
  : `No meeting in the register matches "${q}".`;
return [{ json: { result: `Register search (${rows.length} meetings saved):\n${text}` } }];
